CREATE TABLE IF NOT EXISTS suites (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cases (id TEXT PRIMARY KEY,suite_id TEXT NOT NULL REFERENCES suites(id),title TEXT NOT NULL,prompt TEXT NOT NULL,expected_contains TEXT NOT NULL,forbidden_contains TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS targets (id TEXT PRIMARY KEY,name TEXT NOT NULL,system_prompt TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY,suite_id TEXT NOT NULL,target_id TEXT NOT NULL,status TEXT NOT NULL,cursor INTEGER NOT NULL,passed INTEGER NOT NULL,failed INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS results (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,case_id TEXT NOT NULL,output TEXT NOT NULL,passed INTEGER NOT NULL,reasons TEXT NOT NULL,latency_ms INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cases_suite ON cases(suite_id);
CREATE INDEX IF NOT EXISTS results_run ON results(run_id);
